  "chord.res.cvL.sets": "cada segmento revisado en {m} puntos",
  "chord.res.ncL.sets": "{a} en la primera prueba, {b} entre los segmentos al azar",
  "chord.res.worst": "Mayor falla de la primera prueba",
  "chord.res.worstL.fn": "altura de f₂ sobre la cuerda, en x = {x}",
